ExperienceSnapshot DataSource::fetch_experience() const {
    const FetchResult raw = fetch_experience_raw();
    if (!raw.ok) {
        ExperienceSnapshot snap;
        snap.unavailable_reason = raw.error;
        return snap;
    }
    return parse_experience(raw.json);
