69	MainWindow::MainWindow(QWidget* parent) : QMainWindow(parent) {
70	    setWindowTitle(QStringLiteral("WeakNet 诊断看板"));
71	    resize(1024, 700);
72	    build_ui();
73	
74	    fetcher_ = new DataFetchThread(this);
75	
76	    connect(fetcher_, &DataFetchThread::experienceReady,
77	            this, &MainWindow::onExperienceReady);
78	    connect(fetcher_, &DataFetchThread::diagnosisReady,
79	            this, &MainWindow::onDiagnosisReady);
80	    connect(fetcher_, &DataFetchThread::historyReady,
81	            this, &MainWindow::onHistoryReady);
82	    connect(fetcher_, &DataFetchThread::fetchFailed,
83	            this, &MainWindow::onFetchFailed);
84	    connect(fetcher_, &DataFetchThread::refreshFinished,
85	            this, &MainWindow::onRefreshFinished);
86	
87	    // 自动刷新：QTimer 在主线程，触发时只是给后台线程打个标记，不会阻塞
88	    auto* timer = new QTimer(this);
89	    connect(timer, &QTimer::timeout, this, [this]() {
90	        if (!refresh_in_flight_) {
91	            fetcher_->requestRefresh();
92	        }
