293	void MainWindow::update_status_label(const SleItem& item, QLabel* state_label) {
294	    if (!state_label) {
295	        return;
296	    }
297	
298	    // 不适用的维度（如有线链路下的 RF 健康）显式标注，不显示 GOOD/BAD
299	    if (!item.applicable()) {
300	        state_label->setText(QStringLiteral("不适用"));
301	        state_label->setStyleSheet(QStringLiteral("color: #9E9E9E;"));
302	        return;
303	    }
304	
305	    if (!item.has_value()) {
306	        state_label->setText(QStringLiteral("未知"));
307	        state_label->setStyleSheet(QStringLiteral("color: #9E9E9E;"));
308	        return;
309	    }
310	
311	    // 部分覆盖的维度加后缀，提示结论置信度较低
312	    QString text = QString::fromStdString(item.state);
313	    if (item.coverage == "PARTIAL") {
314	        text += QStringLiteral(" (部分)");
315	    }
316	    state_label->setText(text);
317	    state_label->setStyleSheet(
318	        QStringLiteral("color: %1;").arg(state_color(QString::fromStdString(item.state))));
319	}
