321	QString MainWindow::state_color(const QString& state) {
322	    // 取值依据 server/include/assurance/health_state.hpp:15-23
323	    if (state == QLatin1String("GOOD")) {
324	        return QStringLiteral("#2E7D32");      // 绿
325	    }
326	    if (state == QLatin1String("DEGRADED")) {
327	        return QStringLiteral("#F9A825");      // 黄
328	    }
329	    if (state == QLatin1String("BAD")) {
330	        return QStringLiteral("#C62828");      // 红
331	    }
332	    return QStringLiteral("#9E9E9E");          // 灰（UNKNOWN）
