    EXPECT_FALSE(JsonReader("").valid());
    EXPECT_FALSE(JsonReader("   ").valid());
    EXPECT_FALSE(JsonReader("null").valid());
    EXPECT_FALSE(JsonReader("\"a string\"").valid());
    EXPECT_FALSE(JsonReader("<html>500</html>").valid());
}

