    EXPECT_TRUE(JsonReader("{}").valid());
    EXPECT_TRUE(JsonReader("[]").valid());
    EXPECT_TRUE(JsonReader("  {\"a\":1}  ").valid());
    EXPECT_TRUE(JsonReader("[1,2,3]").valid());
}

